# -*- coding: utf-8 -*-
"""Round92 B17+B18 blind predictions writer. Data only from input cards + kb-snapshot method."""
import json, os
OUT = "/home/hatch/workspace/divination/benchmark/phase3/runs/round92/predictions"
os.makedirs(OUT, exist_ok=True)
P = {}
def add(cid, text, basis, conf, trig=None):
    if trig is None:
        trig = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
    P[cid] = {"case_id": cid, "prediction_text": text, "basis": basis, "confidence": conf, "trigger": trig}
def lytrig(reason):
    return {"changed_main": False, "reserve_used": False, "disputed": False, "reason": reason}

